INSERT INTO _v4_staging (stock_code, instrument_name, primary_market_code, security_type, listing_date) VALUES
INSERT INTO public.stock_instruments (stock_code, instrument_name, primary_market_code, security_type, currency_code, listing_date, listing_status, is_active, source_id) SELECT stock_code, instrument_name, primary_market_code, security_type, 'KRW', listing_date, 'LISTED', TRUE, (SELECT id FROM public.stock_data_sources WHERE source_code = 'KRX_OPEN_API') FROM _v4_staging ON CONFLICT (stock_code, primary_market_code) DO UPDATE SET instrument_name = EXCLUDED.instrument_name, security_type = EXCLUDED.security_type, currency_code = EXCLUDED.currency_code, listing_date = EXCLUDED.listing_date, listing_status = EXCLUDED.listing_status, is_active = EXCLUDED.is_active, source_id = EXCLUDED.source_id;